import type { TFunction } from 'i18next';
import type { Notification } from '@/types/notification';
import { statusChangeErrorText } from '@/lib/status-change-error';

/**
 * i18n keys a notification may carry in `data.i18n` (see the backend's
 * `src/common/notification_i18n.py`): `<namespace>:<key>` keys for its title
 * and description, and the values of their `{{placeholders}}`. The stored
 * English texts are the fallback.
 *
 * A description of several lines (an approval step's "Approval Required")
 * comes as `descriptionLines`: one text per line, each with its key, its
 * params and its English text; a param can itself be such a text.
 */
export interface NotificationI18n {
  title?: string;
  description?: string;
  params?: Record<string, string>;
  descriptionLines?: I18nText[];
  /**
   * Namespace whose `status.<status>` keys label the statuses in `params`
   * (`fromStatus`, `toStatus`, `currentStatus`), e.g. `data-contracts`.
   */
  statusNamespace?: string;
  /**
   * The coded error of a refused status change. When present, `params.reason`
   * (its English text) is replaced by the translated error.
   */
  error?: { code?: string; message?: string; params?: Record<string, unknown> };
}

export interface I18nText {
  key?: string;
  params?: Record<string, unknown>;
  text?: string;
}

const STATUS_PARAMS = ['fromStatus', 'toStatus', 'currentStatus'];

/** The params of the texts, with statuses and a refusal reason in the user's language. */
function translatedParams(i18n: NotificationI18n | null, t: TFunction): Record<string, string> | undefined {
  if (!i18n?.params) return i18n?.params;
  const params = { ...i18n.params };
  const namespace = i18n.statusNamespace;
  if (namespace) {
    for (const name of STATUS_PARAMS) {
      if (params[name]) {
        params[name] = t(`${namespace}:status.${params[name]}`, { defaultValue: params[name] }) as string;
      }
    }
  }
  if (i18n.error?.code && 'reason' in params) {
    params.reason = statusChangeErrorText(
      {
        error: i18n.error.message || params.reason,
        errorCode: i18n.error.code,
        errorParams: i18n.error.params ?? null,
      },
      t,
      namespace || 'data-products',
    );
  }
  return params;
}

type NotificationText = Pick<Notification, 'title' | 'description' | 'message' | 'data'>;

export function notificationI18n(notification: NotificationText): NotificationI18n | null {
  let data: unknown = notification.data;
  if (typeof data === 'string') {
    try {
      data = JSON.parse(data);
    } catch {
      return null;
    }
  }
  const i18n = (data as { i18n?: unknown } | null | undefined)?.i18n;
  return i18n && typeof i18n === 'object' ? (i18n as NotificationI18n) : null;
}

/**
 * The label of an entity type written raw (`data_product`) in a text's params:
 * the approval notifications' label, else the workflows' one, else the raw value.
 */
function entityTypeParam(t: TFunction, value: unknown): unknown {
  if (typeof value !== 'string' || !value) return value;
  return t(
    [`notifications:workflowDefaults.approval.entityTypes.${value}`, `common:workflows.entityTypes.${value}`],
    { defaultValue: value },
  ) as string;
}

function translate(t: TFunction, key: string | undefined, fallback: string, params?: Record<string, unknown>) {
  if (!key) return fallback;
  const shown = params && 'entity_type' in params
    ? { ...params, entity_type: entityTypeParam(t, params.entity_type) }
    : params;
  return t(key, { ...(shown || {}), defaultValue: fallback }) as string;
}

function isI18nText(value: unknown): value is I18nText {
  return !!value && typeof value === 'object' && ('key' in value || 'text' in value);
}

function translateText(t: TFunction, text: I18nText): string {
  const params = Object.fromEntries(
    Object.entries(text.params || {}).map(([name, value]) => [
      name, isI18nText(value) ? translateText(t, value) : value,
    ]),
  );
  return translate(t, text.key, text.text ?? '', params);
}

/** The notification's title in the user's language, or its stored text. */
export function notificationTitle(notification: NotificationText, t: TFunction): string {
  const i18n = notificationI18n(notification);
  return translate(t, i18n?.title, notification.title, translatedParams(i18n, t));
}

/** The notification's description (or message) in the user's language, or its stored text. */
export function notificationDescription(notification: NotificationText, t: TFunction): string {
  const fallback = notification.description || notification.message || '';
  const i18n = notificationI18n(notification);
  if (Array.isArray(i18n?.descriptionLines) && i18n.descriptionLines.length) {
    return i18n.descriptionLines
      .map(line => (isI18nText(line) ? translateText(t, line) : String(line ?? '')))
      .join('\n');
  }
  return translate(t, i18n?.description, fallback, translatedParams(i18n, t));
}

/**
 * The approval notification's action payload for the approval dialog, with its
 * `workflow_message` in the user's language when the notification carries the
 * key of a shipped message. Otherwise the payload is returned as stored.
 */
export function approvalActionPayload(
  notification: NotificationText & { action_payload?: Record<string, any> | null },
  t: TFunction,
): Record<string, any> | undefined {
  const payload = notification.action_payload ?? undefined;
  const lines = notificationI18n(notification)?.descriptionLines;
  const message = Array.isArray(lines)
    ? lines.find(line => line?.key?.endsWith('.approval.lines.workflowMessage'))?.params?.message
    : undefined;
  if (!payload || !isI18nText(message) || !message.key) return payload;
  return { ...payload, workflow_message: translateText(t, message) };
}
